// EmitOcticon writes an inline <svg> with the named octicon at (x, y), sized
// (size × size). fill is a CSS color string (e.g. "#959da5"). Unknown names
// emit nothing — caller falls through gracefully.
func EmitOcticon(w io.Writer, x, y, size int, name, fill string) {
	d, ok := Octicons[name]
	if !ok {
		return
	}
	// fill-rule="evenodd" is required: 16px octicons encode interior
	// cutouts as inner closed loops; the SVG default ("nonzero") fills them.
	fmt.Fprintf(w, `<svg x="%d" y="%d" width="%d" height="%d" viewBox="0 0 16 16"><path fill="%s" fill-rule="evenodd" d="%s"/></svg>`,
		x, y, size, size, fill, d)
}
